        "Parafjala kërkon rasën dhanore (Dativ): ab nächstem Monat, ab dem 1. Mai. Para datës shpesh qëndron pa nyjë: ab Montag, ab morgen. Ab është edhe parashtesë e ndashme: abfahren (nisem), abholen (marr, tërheq).",
