        "Fjala nuk ndryshon. Bitte schön është variant më i sjellshëm kur ofron diçka („urdhëroni“), bitte sehr — variant i barasvlershëm. Wie bitte? do të thotë „si thatë?“, kur nuk ke dëgjuar mirë.",
