        "Da mund të jetë edhe ndajfolje kohe me kuptimin „atëherë“ (Da kam er) dhe lidhëz nënrenditëse me kuptimin „meqë“: Da es regnet, bleiben wir zu Hause — në fjalinë e varur folja është në fund.",
