      "layout": "standardStudy",
      "translation": "ky",
      "explanation": [
        "Ideja kryesore: dieser tregon një person ose send të afërt: dieser Mann (ky burrë), diese Frau (kjo grua), dieses Kind (ky fëmijë), diese Kinder (këta fëmijë).",
        "Lakohet si nyja shquese der: Nominativ dieser/diese/dieses, Akkusativ diesen (gjinia mashkullore), Dativ diesem/dieser/diesem. Në shumës: diese, diesen. Forma asnjanëse dieses Jahr do të thotë „këtë vit“.",
        "Dieser përdoret edhe në vend të emrit, me mbaresë rasore, kur është e qartë për çfarë bëhet fjalë: Dieser gefällt mir (ky më pëlqen)."
      ],
      "examples": [
        {
          "de": "Dieser Tisch ist neu.",
          "lv": "Kjo tavolinë është e re."
        },
        {
          "de": "Ich kaufe diese Jacke.",
          "lv": "Unë e blej këtë xhaketë."
        },
        {
          "de": "Dieses Kind heißt Lena.",
          "lv": "Ky fëmijë quhet Lena."
        },
        {
          "de": "Kennst du diesen Mann?",
          "lv": "A e njeh këtë burrë?"
        },
        {
          "de": "Mit diesem Auto fahre ich nicht.",
          "lv": "Me këtë makinë nuk udhëtoj."
        }
      ],
      "comparison": [
        {
          "word": "jener",
          "meaning": "ai (më larg)",
          "example": "Jener Mann dort ist mein Chef. – Ai burrë atje është shefi im."
        },
        {
          "word": "der",
          "meaning": "nyja shquese",
          "example": "Der Tisch ist neu. – Tavolina është e re."
        },
        {
          "word": "dies",
          "meaning": "ky (përemër)",
          "example": "Dies ist mein Bruder. – Ky është vëllai im."
        }
      ],
      "tip": [
        "Dieser lakohet si der: der Mann → dieser Mann, den Mann → diesen Mann.",
        "Dieses Jahr = këtë vit, diese Woche = këtë javë."
      ],
      "important": [
        "Mbaresa e dieser varet nga gjinia, rasa dhe numri i emrit: diesen Mann, diesem Mann.",
        "Dieser tregon diçka më të afërt; për diçka më të largët mund të përdoret jener (më rrallë) ose der/die/das i theksuar."
      ],
