        "Format: hört, hörte, hat gehört; me kallëzore: etwas hören. Me von: von jemandem hören — marr lajme nga dikush (Ich habe lange nichts von ihm gehört).",
        "Kur dëgjon me vëmendje një njeri, përdoret zuhören me dhanore: Ich höre dir zu."
