        "Shkalla krahasore është jünger (me umlaut), sipërorja — am jüngsten: Er ist jünger als ich. Para emrit: ein junger Mann, eine junge Frau, junge Leute.",
        "E kundërta: alt (i vjetër, plak). Emri der Junge (shumës die Jungen) do të thotë „djalë”, jo „i ri”."
