        "Format: ich laufe, du läufst, er läuft; lief, ist gelaufen. Folja ndihmëse është sein: Er ist gelaufen. Pyetje: Wie läuft’s? — Si shkon?",
        "Me drejtim laufen do të thotë eci në këmbë, jo udhëtoj me mjet: Wir laufen zur Schule. Vrapimi i shpejtë shpesh shprehet me rennen."
