        "Ideja kryesore: laut është mbiemër dhe ndajfolje: „i zhurmshëm, me zë të lartë”: Die Musik ist laut. Përshkruan tingullin, një vend me zhurmë ose zërin: Sprich nicht so laut!",
        "Shkalla krahasore: lauter (më fort), sipërorja: am lautesten. Para emrit: ein lauter Knall, laute Musik. E kundërta është leise.",
        "Laut është edhe parafjalë me kuptimin „sipas” (laut Gesetz — sipas ligjit), por kjo është fjalë tjetër; emri der Laut do të thotë „tingull”."
