        "Lidhje të shpeshta: morgen früh (nesër në mëngjes), morgen Abend (nesër në mbrëmje), bis morgen (shihemi nesër), übermorgen (pasnesër). Pjesët e ditës pas morgen shkruhen me shkronjë të madhe: morgen Nachmittag.",
        "Dallimi nga Morgen: der Morgen është emër me kuptimin „mëngjes”, ndërsa morgen është ndajfolje me kuptimin „nesër”. Në fillim të fjalisë dallohen vetëm nga kuptimi."
