        "Format: ich muss, du musst, er/sie/es muss, wir müssen, ihr müsst, sie müssen; musste, hat gemusst. Folja e dytë qëndron në paskajore në fund të fjalisë: Ich muss heute arbeiten.",
        "E rëndësishme: nicht müssen do të thotë „nuk është e nevojshme, s’ka nevojë”, jo „nuk lejohet”: Du musst nicht kommen — nuk ke nevojë të vish. „Nuk lejohet” është nicht dürfen."
